const TOPICS = [{"id": "jly", "name": "J vagy ly?", "sub": "A kétarcú hang", "grade": 5, "icon": "j / ly", "rule": "A j hangot kétféle betű jelölheti. A szócsaládok segítenek, de sok szó írásképét meg kell jegyeznünk.", "pages": "63–65."}, {"id": "vowel", "name": "Ékezetküldetés", "sub": "Rövid vagy hosszú?", "grade": 5, "icon": "í ú ű", "rule": "Figyelj a magánhangzók időtartamára! A szótő és a toldalék is számít; a víz és a vizes például eltérő tövet mutat.", "pages": "52–55."}, {"id": "consonant", "name": "Hangnyomozó", "sub": "Egy vagy két betű?", "grade": 5, "icon": "ssz", "rule": "A hosszú mássalhangzót kettőzéssel jelöljük. A hosszú többjegyű betűnek egy szóban rendszerint csak az első jegyét kettőzzük.", "pages": "54–55., 65."}, {"id": "stem", "name": "Szóelemlabor", "sub": "A kiejtés mögött", "grade": 5, "icon": "+", "rule": "A szóelemző írásmód megőrzi a felismerhető szóelemeket akkor is, ha kiejtéskor a hangok módosulnak.", "pages": "60–62."}, {"id": "principle", "name": "Szabályőrség", "sub": "A négy alapelv", "grade": 5, "icon": "4", "rule": "Kiejtés, szóelemzés, hagyomány és egyszerűsítés: egy szó írásában több elv is szerepet játszhat. A feladat a kiemelt jelenségre kérdez.", "pages": "52–65."}, {"id": "split", "name": "Szótaghíd", "sub": "Biztos elválasztás", "grade": 5, "icon": "el-", "rule": "A szótagolás és az összetételi tagok határa segít. Elválasztáskor a kettőzött kétjegyű betű mindkét jegyét kiírjuk mindkét oldalon.", "pages": "45–48."}, {"id": "name", "name": "Névváros", "sub": "Kisbetű, nagybetű", "grade": 5, "icon": "Aa", "rule": "A tulajdonneveket nagybetűvel kezdjük. A köznevek mondat belsejében általában kisbetűsek. A mondatkezdés ettől külön szabály.", "pages": "40–41., 63–65.; alapozó ismétlés"}, {"id": "date", "name": "Időkapu", "sub": "Dátumok és mondatvégek", "grade": 5, "icon": "12.", "rule": "Az önálló keltezésben az év és a nap száma után pont áll. A hónap kiírt neve kisbetűs. A naphoz kapcsolt toldalék előtt elmarad a pont.", "pages": "49–51."}, {"id": "geo", "name": "Térképtitkok", "sub": "Földrajzi nevek helyesírása", "grade": 6, "icon": "É–D", "rule": "A név szerkezete számít: egybeírt név, kötőjeles név vagy különírt név. A ragok és az -i képző nem azonos módon kapcsolódnak. A tulajdonnévi előtag egyes képzett alakokban megőrzi a nagybetűjét.", "pages": "6. évfolyamos alapok; AkH. 172–183."}, {"id": "proper", "name": "Névműhely", "sub": "Tulajdonnevek és képzők", "grade": 6, "icon": "-i", "rule": "A személynevek, földrajzi nevek, intézménynevek, címek és díjak külön szabályokat követnek. A névtípus és a toldalék együtt határozza meg az írásképet.", "pages": "6. évfolyamos szófajtani alapok"}, {"id": "verb", "name": "Igekötőkikötő", "sub": "Együtt vagy külön?", "grade": 6, "icon": "meg", "rule": "Az igekötőt a saját igéje előtt közvetlenül egybeírjuk; az ige után és közbeékelt más szó esetén külön. Figyelj a jelentésre is!", "pages": "6. évfolyamos szófajtani alapok"}, {"id": "number", "name": "Számsziget", "sub": "Számnevek és melléknevek", "grade": 6, "icon": "2000", "rule": "A számneveket kétezerig egybeírjuk. Kétezren felül a nem kerek ezreseket hármas számcsoportok szerint kötőjellel tagoljuk. A fokjelet kettőzött b jelöli.", "pages": "6. évfolyamos szófajtani alapok"}, {"id": "compound", "name": "Összetétel-erőd", "sub": "Jelentés és szóhatár", "grade": 7, "icon": "egybe", "rule": "Az összetételek írásában a jelentés, a jelöltség és a hagyomány is számít. A két tagból álló összetételek hosszúságuktól függetlenül egybeírhatók.", "pages": "7. tankönyv 24–36."}, {"id": "hyphen", "name": "Kötőjelöböl", "sub": "Összetett kihívások", "grade": 7, "icon": "-", "rule": "A mellérendelő összetételek toldalékolása fontos. A kettőnél több tagból álló, hat szótagnál hosszabb összetételeket a fő határon kötőjellel tagoljuk; a jeleket, ragokat és az -i képzőt nem számítjuk a szótagszámba.", "pages": "7. tankönyv 34–36."}, {"id": "sentence", "name": "Mondatmentők", "sub": "Központozás a gyakorlatban", "grade": 7, "icon": "!?", "rule": "A mondatkezdés, a mondatzárás, a felsorolás és az értelmező központozása együtt teszi világossá a mondatot.", "pages": "7. tankönyv 38–44., 52–56., 84–87."}, {"id": "sim5", "name": "Simonyi-műhely 5.", "sub": "Versenyfeladatok újragondolva", "grade": 5, "icon": "SZ", "rule": "Olvasd el pontosan a feladatot! A szó jelentése, a szóelemek, a névtípus és a toldalék együtt segít. Ezek versenyfeladatokból átdolgozott, nehezebb kihívások.", "pages": "Simonyi 2023 · 5. évfolyamos feltöltött gyakorlóteszt"}, {"id": "sim6", "name": "Simonyi-műhely 6.", "sub": "Versenyfeladatok újragondolva", "grade": 6, "icon": "SZ", "rule": "Olvasd el pontosan a feladatot! A szó jelentése, a szóelemek, a névtípus és a toldalék együtt segít. Ezek versenyfeladatokból átdolgozott, nehezebb kihívások.", "pages": "Simonyi 2023 · 6. évfolyamos feltöltött gyakorlóteszt"}, {"id": "sim7", "name": "Simonyi-műhely 7.", "sub": "Versenyfeladatok újragondolva", "grade": 7, "icon": "SZ", "rule": "Olvasd el pontosan a feladatot! A szó jelentése, a szóelemek, a névtípus és a toldalék együtt segít. Ezek versenyfeladatokból átdolgozott, nehezebb kihívások.", "pages": "Simonyi 2023 · 7. évfolyamos feltöltött gyakorlóteszt"}, {"id": "clauses", "name": "Vesszőlabirintus", "sub": "Tagmondatok és mondatzárás", "grade": 8, "icon": ",", "rule": "Az összetett mondat tagmondatait elválasztjuk egymástól. Az és előtt is kell vessző, ha tagmondathatáron áll. Alárendeléskor rendszerint a főmondat szabja meg a záró írásjelet.", "pages": "8. tankönyv 83–85."}, {"id": "quotes", "name": "Idézetműhely", "sub": "Idézőjelek és gondolatjelek", "grade": 8, "icon": "„ ”", "rule": "A bevezető idéző mondat után kettőspont áll. A hátravetett idéző mondatot gondolatjel kapcsolja, kisbetűvel kezdjük; az előtte álló idézet záró pontját ilyenkor elhagyjuk. A kérdőjel és a felkiáltójel megmarad.", "pages": "8. tankönyv 86–87.; AkH. 257–259."}, {"id": "acronym", "name": "Mozaikműhely", "sub": "Betűszók, rövidítések, toldalékok", "grade": 8, "icon": "MTA", "rule": "A betűszóhoz kötőjellel kapcsoljuk a toldalékot. A rövidítés pontja a hozzá kapcsolt toldalék előtt is megmarad. A kezdőbetűk és a hangosan kimondott alak is fontos.", "pages": "8. tankönyv 30–32.; AkH. 275–289."}, {"id": "advanced", "name": "Mesterfok", "sub": "Mozgószabályok és névkapcsolatok", "grade": 8, "icon": "+ −", "rule": "A mozgószabályok megváltoztathatják az összetétel belső írását. A különírt szerkezethez járuló közös utótag előtt egybeírjuk az alapkapcsolatot. Egyes tulajdonnévi és betűszós kapcsolatokban több kötőjel is állhat.", "pages": "8. tankönyv 43–47.; AkH. 140–141., 166."}];
